xpath.script:
(function () {
    function normalizeOdooPath(val) {
        if (!val || typeof val !== 'string') {
            return val;
        }
        if (val === '/odoo' || val === '/odoo/' || val === '/odoo?') {
            return '/';
        }
        if (val.startsWith('/odoo?')) {
            return '/' + val.slice(5);
        }
        if (val.startsWith('/odoo#')) {
            return '/' + val.slice(5);
        }
        if (val.startsWith('/odoo/')) {
            return val.replace(/^\/odoo\//, '/');
        }
        return val;
    }

    // 1. Clean redirect param from Query String (e.g. /web/login?redirect=/odoo?)
    try {
        const urlObj = new URL(window.location.href);
        let updated = false;

        if (urlObj.searchParams.has('redirect')) {
            const redirectVal = urlObj.searchParams.get('redirect');
            const cleanedRedirect = normalizeOdooPath(redirectVal);
            if (cleanedRedirect !== redirectVal) {
                urlObj.searchParams.set('redirect', cleanedRedirect);
                updated = true;
            }
        }

        // 2. Clean the Path itself if starting with /odoo
        const cleanedPath = normalizeOdooPath(urlObj.pathname);
        if (cleanedPath !== urlObj.pathname) {
            urlObj.pathname = cleanedPath;
            updated = true;
        }

        if (updated) {
            window.history.replaceState(window.history.state, '', urlObj.toString());
        }
    } catch (e) {}

    // 3. Patch History API for client-side navigation
    function stripOdooPrefix(url) {
        if (!url) return url;
        try {
            const isAbsolute = /^https?:\/\//i.test(url);
            const base = isAbsolute ? undefined : window.location.origin;
            const parsed = new URL(url, base);
            let changed = false;

            if (parsed.searchParams.has('redirect')) {
                const rVal = parsed.searchParams.get('redirect');
                const cleanedRVal = normalizeOdooPath(rVal);
                if (cleanedRVal !== rVal) {
                    parsed.searchParams.set('redirect', cleanedRVal);
                    changed = true;
                }
            }

            const cleanedPathname = normalizeOdooPath(parsed.pathname);
            if (cleanedPathname !== parsed.pathname) {
                parsed.pathname = cleanedPathname;
                changed = true;
            }
            if (!changed) {
                return url;
            }
            return isAbsolute ? parsed.toString() : parsed.pathname + parsed.search + parsed.hash;
        } catch (e) {
            return url;
        }
    }

    const nativePush = window.history.pushState.bind(window.history);
    const nativeReplace = window.history.replaceState.bind(window.history);

    window.history.pushState = function (state, title, url) {
        return nativePush(state, title, stripOdooPrefix(url));
    };

    window.history.replaceState = function (state, title, url) {
        return nativeReplace(state, title, stripOdooPrefix(url));
    };
})();
